using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() now uses UTC for seeding timestamps.
        // Use a fixed value instead of DateTime.UtcNow for deterministic migrations.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking-change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change #1: Cosmos provider now uses "$type" instead of
            // "Discriminator" for the discriminator property by default.
            // Fix: Explicitly configure the old property name for existing documents.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

// EF Core 9 breaking change #2: Synchronous I/O on Cosmos DB now throws by default.
// All Cosmos queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.).
class ProductService
{
    private readonly CosmosDbContext _db;
    public ProductService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 — worked with sync):
    //   var products = _db.Products.Where(p => p.Category == category).ToList();
    //
    // AFTER (EF Core 9 — must use async):
    public async Task<List<Product>> GetByCategoryAsync(string category)
    {
        return await _db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }
}

