arguments.new_str:
using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change #3: Migrate() can no longer be called inside a
    // manual transaction — it now manages its own transaction internally.
    // Fix: Remove the wrapping BeginTransaction/Commit; rely on the execution strategy retry.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

